import { notFound } from "next/navigation";
import Link from "next/link";
import { requireAdminPage } from "@/lib/admin/page-auth";
import { getAdminUser } from "@/lib/admin/queries";
import { UserControls } from "@/components/admin/user-controls";
import { AdminNotice, dateLabel } from "@/components/admin/common";
export default async function UserPage({
  params,
}: {
  params: Promise<{ userId: string }>;
}) {
  const actor = await requireAdminPage(),
    { userId } = await params;
  let u;
  try {
    u = await getAdminUser(userId);
  } catch {
    return <AdminNotice />;
  }
  if (!u) notFound();
  return (
    <>
      <h1 className="text-3xl font-semibold">{u.name || u.email}</h1>
      <p className="break-all">
        {u.email} · {u.id}
      </p>
      <dl className="grid gap-3 sm:grid-cols-2">
        <div>
          <dt>Access</dt>
          <dd>
            {u.effectivePlan} (base {u.plan}) · {u.subscriptionStatus}
          </dd>
        </div>
        <div>
          <dt>Account</dt>
          <dd>
            {u.isSuspended ? "Suspended" : "Active"} ·{" "}
            {u.reconnectRequired
              ? "Gmail reconnect required"
              : "Gmail connected"}
          </dd>
        </div>
        <div>
          <dt>Signed up</dt>
          <dd>{dateLabel(u.createdAt)}</dd>
        </div>
        <div>
          <dt>Last active</dt>
          <dd>{dateLabel(u.lastActiveAt)}</dd>
        </div>
        <div>
          <dt>Provider period</dt>
          <dd>
            {dateLabel(u.currentPeriodStart)} – {dateLabel(u.currentPeriodEnd)}
          </dd>
        </div>
        <div>
          <dt>Grace deadline</dt>
          <dd>{dateLabel(u.gracePeriodEnd)}</dd>
        </div>
        <div>
          <dt>Override</dt>
          <dd>
            {u.planOverride ?? "None"} · {dateLabel(u.planOverrideStartsAt)} –{" "}
            {dateLabel(u.planOverrideExpiresAt)}
          </dd>
        </div>
      </dl>
      <section>
        <h2 className="mb-3 text-xl font-semibold">Usage · {u.usage.state}</h2>
        {u.usage.state !== "VERIFIED" ? (
          <p>
            Accounting is unresolved or unverified. Remaining allowance is
            unknown.
          </p>
        ) : (
          <div className="grid gap-4 sm:grid-cols-2">
            {[u.usage.daily, u.usage.monthly].map(
              (a, i) =>
                a && (
                  <div key={i}>
                    <h3>{a.label}</h3>
                    <p>
                      {a.sent} confirmed/imported sent · {a.reserved} reserved
                      (including uncertain attempts)
                    </p>
                    <p>
                      {a.remaining} remaining of {a.limit}
                    </p>
                    <p className="text-sm text-body">
                      {dateLabel(a.startsAt)} – {dateLabel(a.resetsAt)}
                    </p>
                  </div>
                ),
            )}
          </div>
        )}
      </section>
      <UserControls user={u} self={actor.id === u.id} />
      <Link className="underline" href={`/admin/audit?targetId=${u.id}`}>
        View this user’s audit history
      </Link>
    </>
  );
}
